const ui={theme:load('theme','light'),tab:load('tabs',{}),selected:new Set(load('selected',[])),multiGroups:new Set(load('multiGroups',[])),multiSubs:new Set(load('multiSubs',[])),filters:{query:'',status:'All statuses',page:1,size:10,sort:'name',dir:1,density:'Comfortable'},columns:new Set(load('columns',['id','name','email','group','sub','status'])),rpt:{query:'',status:'All statuses',page:1},cfg:load('config',cfgDefault),draft:load('draft',{subject:'Your upcoming class details',sender:'SkillMonk Academy',reply:'support@example.com',type:'Class Schedule',message:'Hello {{student_name}},\n\nWe are pleased to confirm your upcoming class.\n\nCourse: {{course_name}}\nBatch: {{batch_name}}\nDate: 18 October 2026\nTime: 10:00 AM IST\n\nPlease log in to your student portal before the class begins.\n\nBest regards,\nLearning Support Team',when:'now',date:'2026-10-18T10:00',attachments:[]}),extras:load('queueExtras',[]),pause:false,queueQuery:'',queueStatus:'All statuses',eventTab:'all',templates:load('templates',null),portalKind:'SkillMonk Academy'};
