function statusBadge(s){const l=String(s).toLowerCase(),c=/sent|delivered|active|confirmed|healthy|enabled|verified|completed|connected|ready/.test(l)?'good':/fail|bounce|complaint|cancel|blocked|unsubscribed|suppressed/.test(l)?'bad':/scheduled|pending|queue|rescheduled|deferred|inactive/.test(l)?'warn':'blue';return `<span class="badge ${c}">${esc(s)}</span>`}
