function toast(msg){let area=document.getElementById('toast-area');if(!area)return;let t=document.createElement('div');t.className='toast';t.innerHTML=`${icon('check')} <span>${esc(msg)}</span>`;area.append(t);setTimeout(()=>t.remove(),4200)}
