function buildChart(){const values=[90,111,104,136,142,120,153,180,163,194,209,191,212,254,233,264,241,292,275,322,305,313,335,349,322,368,358,389];const W=760,H=212,p=24,b=28;const max=420;const X=i=>p+i*(W-2*p)/(values.length-1),Y=n=>H-b-n/max*(H-2*p);const curve=values.map((n,i)=>`${i?'L':'M'}${X(i).toFixed(1)} ${Y(n).toFixed(1)}`).join(' ');const c2=values.map((n,i)=>`${i?'L':'M'}${X(i).toFixed(1)} ${Y(n*.72+(i%5)*5).toFixed(1)}`).join(' ');return `<svg class="chart-svg" viewBox="0 0 ${W} ${H}" aria-label="Illustrative email delivery volume chart"><defs><linearGradient id="plotshade" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#347afd" stop-opacity=".18"/><stop offset="1" stop-color="#347afd" stop-opacity="0"/></linearGradient></defs>${[100,200,300,400].map(n=>`<line x1="${p}" y1="${Y(n)}" x2="${W-p}" y2="${Y(n)}" stroke="#e7ecf5" stroke-dasharray="3 5"/><text x="1" y="${Y(n)+4}" font-size="10" fill="#8392a8">${n}</text>`).join('')}<path d="${curve} L${W-p} ${H-b} L${p} ${H-b}Z" fill="url(#plotshade)"/><path d="${curve}" stroke="#347afd" stroke-width="3" fill="none" stroke-linecap="round" stroke-linejoin="round"/><path d="${c2}" stroke="#32b9a9" stroke-width="2.5" fill="none" stroke-linecap="round" stroke-linejoin="round"/>${['Sep 19','Sep 26','Oct 03','Oct 10','Oct 16'].map((s,i)=>`<text x="${p+8+i*(W-2*p)/4}" y="${H-5}" text-anchor="middle" font-size="10" fill="#8392a8">${s}</text>`).join('')}</svg>`}
